def calculate_m(sequence):
    N = len(sequence)
    m = 0
    for i in range(N):
        for j in range(i + 1, N):
            if sequence[j] == sequence[i] + 1:
                for k in range(j + 1, N):
                    if sequence[k] == sequence[j] + 1:
                        m += 1
    return m

# N=5 test case
A5 = [1, 1, 2, 2, 3]
